import { supabase } from './client'

export type Goal = {
  id: string
  projectId?: string
  title: string
  progress: number
  linkedObjectives: number
  createdAt: string
}

export const goalsService = {
  async listGoals(projectId?: string): Promise<Goal[]> {
    let query = supabase.from('goals').select('*').order('created_at', { ascending: false })
    if (projectId) query = query.eq('project_id', projectId)
    const { data, error } = await query
    if (error) throw error
    return (data ?? []) as Goal[]
  },

  async createGoal(payload: { title: string; projectId?: string }): Promise<Goal> {
    const { data, error } = await supabase
      .from('goals')
      .insert({ title: payload.title, project_id: payload.projectId, progress: 0 })
      .select()
      .single()
    if (error) throw error
    return data as Goal
  },
}
